// Hand-made stroke templates for the $P recogniser: digits, Roman numerals
// I and V, note names A-G and the accidentals sharp (#) and flat (b).
// Each stroke is a list of control points in a unit box (y grows downwards);
// "c" strokes are smoothed with a Catmull-Rom spline, "l" strokes are polylines.
// Every template is also stored slanted left and right, since children's
// handwriting leans both ways.
(function (g) {
  const HW = (g.HW = g.HW || {});

  const c = (...p) => ({ curve: true, p });
  const l = (...p) => ({ curve: false, p });

  const DEFS = {
    0: [{ w: 0.7, s: [c([0.5, 0], [0.12, 0.25], [0.1, 0.72], [0.5, 1], [0.9, 0.72], [0.88, 0.25], [0.5, 0])] }],
    1: [
      { w: 0.1, s: [l([0.5, 0], [0.5, 1])] },
      { w: 0.45, s: [l([0.1, 0.25], [0.6, 0], [0.6, 1])] },
      { w: 0.6, s: [l([0.15, 0.25], [0.55, 0], [0.55, 1]), l([0.15, 1], [0.95, 1])] },
    ],
    2: [
      { w: 0.65, s: [c([0.1, 0.25], [0.5, 0], [0.88, 0.25], [0.6, 0.62], [0.08, 1]), l([0.08, 1], [0.95, 1])] },
      { w: 0.65, s: [c([0.1, 0.25], [0.5, 0], [0.88, 0.25], [0.6, 0.62], [0.08, 1], [0.95, 1])] },
    ],
    3: [{ w: 0.6, s: [c([0.1, 0.12], [0.5, 0], [0.85, 0.2], [0.45, 0.48], [0.9, 0.72], [0.5, 1], [0.08, 0.85])] }],
    4: [
      { w: 0.7, s: [l([0.65, 0], [0.05, 0.68], [0.95, 0.68]), l([0.68, 0.25], [0.68, 1])] },
      { w: 0.7, s: [l([0.15, 0], [0.1, 0.6], [0.9, 0.6]), l([0.7, 0.05], [0.7, 1])] },
      { w: 0.7, s: [l([0.7, 1], [0.7, 0], [0.05, 0.68], [0.95, 0.68])] },
    ],
    5: [
      { w: 0.6, s: [l([0.25, 0], [0.2, 0.45]), c([0.2, 0.45], [0.6, 0.4], [0.9, 0.7], [0.55, 1], [0.12, 0.88]), l([0.25, 0], [0.88, 0])] },
      { w: 0.6, s: [l([0.88, 0], [0.25, 0], [0.2, 0.45]), c([0.2, 0.45], [0.6, 0.4], [0.9, 0.7], [0.55, 1], [0.12, 0.88])] },
    ],
    6: [{ w: 0.62, s: [c([0.8, 0.02], [0.35, 0.2], [0.12, 0.65], [0.45, 1], [0.85, 0.75], [0.55, 0.5], [0.15, 0.65])] }],
    7: [
      { w: 0.62, s: [l([0, 0], [1, 0], [0.35, 1])] },
      { w: 0.62, s: [l([0, 0], [1, 0], [0.35, 1]), l([0.3, 0.52], [0.88, 0.52])] },
    ],
    8: [{ w: 0.6, s: [c([0.85, 0.12], [0.5, 0], [0.15, 0.18], [0.5, 0.48], [0.88, 0.75], [0.5, 1], [0.12, 0.75], [0.5, 0.48], [0.85, 0.2])] }],
    9: [
      { w: 0.6, s: [c([0.85, 0.25], [0.5, 0.45], [0.15, 0.25], [0.5, 0], [0.85, 0.2]), l([0.85, 0.2], [0.82, 1])] },
      { w: 0.6, s: [c([0.85, 0.25], [0.5, 0.45], [0.15, 0.25], [0.5, 0], [0.85, 0.2], [0.75, 0.75], [0.4, 1])] },
    ],
    I: [
      { w: 0.1, s: [l([0.5, 0], [0.5, 1])] },
      { w: 0.5, s: [l([0, 0], [1, 0]), l([0.5, 0], [0.5, 1]), l([0, 1], [1, 1])] },
    ],
    V: [
      { w: 0.8, s: [l([0, 0], [0.5, 1], [1, 0])] },
      { w: 0.8, s: [l([0, 0], [0.5, 1]), l([0.5, 1], [1, 0])] },
    ],
    A: [
      { w: 0.85, s: [l([0, 1], [0.5, 0], [1, 1]), l([0.22, 0.6], [0.78, 0.6])] },
      { w: 0.85, s: [l([0, 1], [0.5, 0]), l([0.5, 0], [1, 1]), l([0.22, 0.6], [0.78, 0.6])] },
    ],
    B: [
      { w: 0.7, s: [l([0.1, 0], [0.1, 1]), c([0.1, 0], [0.75, 0.05], [0.75, 0.45], [0.1, 0.5], [0.85, 0.6], [0.85, 0.95], [0.1, 1])] },
      { w: 0.7, s: [c([0.1, 1], [0.1, 0], [0.75, 0.05], [0.75, 0.45], [0.1, 0.5], [0.85, 0.6], [0.85, 0.95], [0.1, 1])] },
    ],
    C: [{ w: 0.75, s: [c([0.9, 0.15], [0.5, 0], [0.1, 0.5], [0.5, 1], [0.9, 0.85])] }],
    D: [
      { w: 0.75, s: [l([0.1, 0], [0.1, 1]), c([0.1, 0], [0.8, 0.15], [0.85, 0.8], [0.1, 1])] },
      { w: 0.75, s: [c([0.1, 1], [0.1, 0], [0.8, 0.15], [0.85, 0.8], [0.1, 1])] },
    ],
    E: [
      { w: 0.65, s: [l([0.1, 0], [0.1, 1]), l([0.1, 0], [0.9, 0]), l([0.1, 0.5], [0.75, 0.5]), l([0.1, 1], [0.9, 1])] },
      { w: 0.65, s: [l([0.9, 0], [0.1, 0], [0.1, 1], [0.9, 1]), l([0.1, 0.5], [0.75, 0.5])] },
    ],
    F: [
      { w: 0.6, s: [l([0.1, 0], [0.1, 1]), l([0.1, 0], [0.9, 0]), l([0.1, 0.5], [0.75, 0.5])] },
      { w: 0.6, s: [l([0.9, 0], [0.1, 0], [0.1, 1]), l([0.1, 0.5], [0.75, 0.5])] },
    ],
    G: [
      { w: 0.8, s: [c([0.9, 0.15], [0.5, 0], [0.1, 0.5], [0.5, 1], [0.9, 0.7]), l([0.9, 0.7], [0.9, 0.55], [0.55, 0.55])] },
      { w: 0.8, s: [c([0.9, 0.15], [0.5, 0], [0.1, 0.5], [0.5, 1], [0.9, 0.7]), l([0.55, 0.55], [0.9, 0.55], [0.9, 1])] },
    ],
    "#": [
      { w: 0.75, s: [l([0.35, 0], [0.3, 1]), l([0.7, 0], [0.65, 1]), l([0, 0.4], [1, 0.3]), l([0, 0.72], [1, 0.62])] },
    ],
    b: [
      { w: 0.55, s: [l([0.15, 0], [0.15, 1]), c([0.15, 0.6], [0.6, 0.45], [0.85, 0.65], [0.5, 0.9], [0.15, 1])] },
      { w: 0.55, s: [c([0.15, 0], [0.15, 1], [0.15, 0.6], [0.6, 0.45], [0.85, 0.65], [0.5, 0.9], [0.15, 1])] },
    ],
  };

  function catmullRom(points, perSegment = 10) {
    const out = [];
    const p = (i) => points[Math.max(0, Math.min(points.length - 1, i))];
    for (let i = 0; i < points.length - 1; i++) {
      const [p0, p1, p2, p3] = [p(i - 1), p(i), p(i + 1), p(i + 2)];
      for (let k = 0; k < perSegment; k++) {
        const t = k / perSegment, t2 = t * t, t3 = t2 * t;
        out.push(
          0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
          0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3),
        );
      }
    }
    const last = points[points.length - 1];
    out.push(last[0], last[1]);
    return out;
  }

  function build(def, slant) {
    return def.s.map((stroke) => {
      const flat = stroke.curve ? catmullRom(stroke.p) : stroke.p.flat();
      const out = new Array(flat.length);
      for (let i = 0; i < flat.length; i += 2) {
        const y = flat[i + 1];
        out[i] = (flat[i] * def.w + slant * (1 - y)) * 100;
        out[i + 1] = y * 100;
      }
      return out;
    });
  }

  HW.templateStrokes = function templateStrokes() {
    const list = [];
    for (const [label, defs] of Object.entries(DEFS)) {
      for (const def of defs) {
        for (const slant of [-0.15, 0, 0.15]) list.push({ label, strokes: build(def, slant) });
      }
    }
    return list;
  };
})(globalThis);
